-- GENERATED by npm run build:database. For a NEW Supabase project only.
-- One transaction: an error rolls back the entire install. Never run on the old test project.
begin;
do $$ begin
 if exists(select 1 from information_schema.tables where table_schema='public' and table_type='BASE TABLE') then
  raise exception 'Fresh install refused: public already contains tables. Use a new empty Supabase project.';
 end if;
end $$;

-- SOURCE: 20261001000000_base_schema.sql
-- Fresh installations only: existing tables are left intact. Apply all migrations in order.
create table if not exists public.businesses (
 id text primary key default gen_random_uuid()::text, owner_user_id uuid unique not null,
 name text not null, owner_name text, owner_email text, owner_phone text, venue_type text,
 country text, city text, address text, opening_hours text, currency_code text default 'EUR',
 currency_symbol text default '€', language text default 'en', setup_completed boolean default false,
 enabled_modules jsonb default '{}'::jsonb, discount_policy jsonb default '{}'::jsonb,
 brand_theme jsonb default '{}'::jsonb, categories jsonb default '[]'::jsonb
);
create table if not exists public.app_users (
 id uuid primary key, business_id text references public.businesses(id), username text not null,
 full_name text, role text not null check (role in ('owner','manager','staff')), email text,
 hourly_rate numeric, numeric_id bigint generated by default as identity
);
create table if not exists public.products (
 id bigint primary key, business_id text not null references public.businesses(id), name_en text not null,
 translations jsonb default '{}', category text, price numeric not null check(price >= 0), emoji text,
 active boolean default true, trans_key text, ingredient_links jsonb default '[]', prepared_stock_links jsonb default '[]',
 extra_ids jsonb default '[]', is_favourite boolean default false, pos_color text
);
create table if not exists public.ingredients (
 id bigint primary key, business_id text not null references public.businesses(id), name text not null,
 unit text, qty numeric not null default 0 check(qty >= 0), low_threshold numeric default 5
);
create table if not exists public.prepared_stock (
 id bigint primary key, business_id text not null references public.businesses(id), name text not null,
 portions numeric not null default 0 check(portions >= 0), low_threshold numeric default 5
);
create table if not exists public.sales (
 id text primary key, business_id text not null references public.businesses(id), subtotal numeric not null,
 payment_method text, cashier_username text, cashier_fullname text, discount_percent numeric default 0,
 discount_amount numeric default 0, tip_amount numeric default 0, tendered_cash numeric, change_given numeric,
 cash_amount numeric, card_amount numeric, status text default 'completed', void_reason text, refunded_at timestamptz,
 customer_name text, customer_phone text, customer_id text, created_at timestamptz default now(), timestamp bigint
);
create table if not exists public.sale_items (
 id bigint generated by default as identity primary key, sale_id text not null references public.sales(id) on delete cascade,
 product_id bigint, qty numeric not null check(qty > 0), unit_price numeric not null, line_total numeric not null,
 extras jsonb default '[]', name_en text, translations jsonb default '{}', note text
);
create table if not exists public.orders (
 id text primary key, business_id text not null references public.businesses(id), type text, status text,
 created_at timestamptz default now(), updated_at timestamptz default now(), scheduled_for timestamptz,
 customer_name text, customer_phone text, items jsonb default '[]', subtotal numeric, payment_method text,
 created_by_username text, created_by_fullname text, completed_at timestamptz, sale_id text,
 discount_amount numeric default 0, tip_amount numeric default 0, void_reason text, kitchen_printed_at timestamptz,
 customer_id text, source text default 'pos', table_id text, table_label text, covers integer
);
create table if not exists public.expenses (
 id text primary key default gen_random_uuid()::text, business_id text not null references public.businesses(id),
 name text, category text, amount numeric, date date, is_recurring boolean default false, frequency text, receipt_image text
);
create table if not exists public.work_shifts (
 id text primary key default gen_random_uuid()::text, business_id text not null references public.businesses(id),
 user_id bigint, username text, full_name text, date date, start_time text, end_time text,
 break_minutes numeric, total_hours numeric, notes text
);
create table if not exists public.rota_shifts (
 id text primary key, business_id text not null references public.businesses(id), username text, "userId" bigint,
 "fullName" text, date date, "startTime" text, "endTime" text, "breakMinutes" numeric, notes text
);


-- SOURCE: 20261002120000_tenant_rls.sql
-- PreVisio tenant RLS: members of a business (via app_users.id = auth.uid()) may access that tenant's rows.
-- Anon has no access to private tenant tables. Public menu/order uses dedicated policies + RPCs where needed.
-- Apply in Supabase SQL editor or: supabase db push

-- Helper: business ids for the current authenticated user
create or replace function public.previsio_my_business_ids()
returns setof text
language sql
stable
security definer
set search_path = public
as $$
  select business_id::text
  from public.app_users
  where id::text = auth.uid()::text
    and business_id is not null;
$$;

revoke all on function public.previsio_my_business_ids() from public;
grant execute on function public.previsio_my_business_ids() to authenticated;

create or replace function public.previsio_is_owner_of(biz_id text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.app_users
    where id::text = auth.uid()::text
      and business_id::text = biz_id
      and role = 'owner'
  );
$$;

revoke all on function public.previsio_is_owner_of(text) from public;
grant execute on function public.previsio_is_owner_of(text) to authenticated;

-- Drop plaintext credential column if present
alter table if exists public.app_users drop column if exists local_password;
alter table if exists public.app_users drop column if exists password;

-- App expects this JSONB map on businesses (onlineOrders, tables, etc.)
alter table if exists public.businesses
  add column if not exists enabled_modules jsonb
  default '{"orders":true,"sales":true,"stock":true,"staff":true,"finance":true,"tables":false,"customers":false,"tips":false,"onlineOrders":false}'::jsonb;

-- Enable RLS on tenant tables (ignore if already enabled)
do $$
declare
  t text;
begin
  foreach t in array array[
    'businesses',
    'app_users',
    'products',
    'ingredients',
    'prepared_stock',
    'sales',
    'sale_items',
    'orders',
    'expenses',
    'work_shifts',
    'rota_shifts'
  ]
  loop
    begin
      execute format('alter table public.%I enable row level security', t);
    exception when undefined_table then
      raise notice 'skip missing table %', t;
    end;
  end loop;
end $$;

-- BUSINESSSES
drop policy if exists previsio_businesses_select on public.businesses;
drop policy if exists previsio_businesses_insert on public.businesses;
drop policy if exists previsio_businesses_update on public.businesses;
drop policy if exists previsio_businesses_delete on public.businesses;

create policy previsio_businesses_select on public.businesses
  for select to authenticated
  using (
    id::text in (select public.previsio_my_business_ids())
    or owner_user_id::text = auth.uid()::text
  );

create policy previsio_businesses_insert on public.businesses
  for insert to authenticated
  with check (owner_user_id::text = auth.uid()::text);

create policy previsio_businesses_update on public.businesses
  for update to authenticated
  using (
    id::text in (select public.previsio_my_business_ids())
    or owner_user_id::text = auth.uid()::text
  )
  with check (
    id::text in (select public.previsio_my_business_ids())
    or owner_user_id::text = auth.uid()::text
  );

create policy previsio_businesses_delete on public.businesses
  for delete to authenticated
  using (public.previsio_is_owner_of(id::text));

-- APP_USERS
drop policy if exists previsio_app_users_select on public.app_users;
drop policy if exists previsio_app_users_insert on public.app_users;
drop policy if exists previsio_app_users_update on public.app_users;
drop policy if exists previsio_app_users_delete on public.app_users;

create policy previsio_app_users_select on public.app_users
  for select to authenticated
  using (
    id::text = auth.uid()::text
    or business_id::text in (select public.previsio_my_business_ids())
  );

-- Owners can insert staff for their business; users can upsert their own owner profile
create policy previsio_app_users_insert on public.app_users
  for insert to authenticated
  with check (
    id::text = auth.uid()::text
    or (
      public.previsio_is_owner_of(business_id::text)
      and coalesce(role, 'staff') <> 'owner'
    )
  );

create policy previsio_app_users_update on public.app_users
  for update to authenticated
  using (
    id::text = auth.uid()::text
    or public.previsio_is_owner_of(business_id::text)
  )
  with check (
    id::text = auth.uid()::text
    or (
      public.previsio_is_owner_of(business_id::text)
      and coalesce(role, 'staff') <> 'owner'
    )
  );

create policy previsio_app_users_delete on public.app_users
  for delete to authenticated
  using (
    public.previsio_is_owner_of(business_id::text)
    and id::text <> auth.uid()::text
  );

-- Generic tenant-scoped tables (business_id column)
do $$
declare
  t text;
  pol text;
begin
  foreach t in array array[
    'products',
    'ingredients',
    'prepared_stock',
    'sales',
    'orders',
    'expenses',
    'work_shifts',
    'rota_shifts'
  ]
  loop
    begin
      execute format('drop policy if exists previsio_%s_all on public.%I', t, t);
      execute format(
        'create policy previsio_%s_all on public.%I for all to authenticated using (business_id::text in (select public.previsio_my_business_ids())) with check (business_id::text in (select public.previsio_my_business_ids()))',
        t, t
      );
    exception when undefined_table then
      raise notice 'skip policies for missing table %', t;
    when undefined_column then
      raise notice 'skip policies for % (no business_id)', t;
    end;
  end loop;
end $$;

-- sale_items: via parent sale
do $$
begin
  begin
    alter table public.sale_items enable row level security;
    drop policy if exists previsio_sale_items_all on public.sale_items;
    create policy previsio_sale_items_all on public.sale_items
      for all to authenticated
      using (
        exists (
          select 1 from public.sales s
          where s.id = sale_items.sale_id
            and s.business_id::text in (select public.previsio_my_business_ids())
        )
      )
      with check (
        exists (
          select 1 from public.sales s
          where s.id = sale_items.sale_id
            and s.business_id::text in (select public.previsio_my_business_ids())
        )
      );
  exception when undefined_table then
    raise notice 'skip sale_items';
  end;
end $$;

-- Public read of active products for businesses with online orders enabled (menu link)
drop policy if exists previsio_products_public_menu on public.products;
do $$
begin
  begin
    create policy previsio_products_public_menu on public.products
      for select to anon, authenticated
      using (
        active is not false
        and exists (
          select 1 from public.businesses b
          where b.id::text = products.business_id::text
            and coalesce((b.enabled_modules->>'onlineOrders')::boolean, false) = true
        )
      );
  exception when undefined_table then
    raise notice 'skip public products policy';
  when undefined_column then
    raise notice 'skip public products policy (schema mismatch)';
  end;
end $$;

-- Online orders are inserted only via server (service role) after price validation.
-- Do not allow anon/authenticated direct inserts — that would bypass price checks.
-- DROP POLICY still errors when the table itself is missing, so skip that case.
do $$
begin
  drop policy if exists previsio_orders_public_insert on public.orders;
exception when undefined_table then
  raise notice 'skip orders public insert policy (table missing)';
end $$;

-- Public can read business name/currency for order page (minimal columns enforced by app select)
do $$
begin
  drop policy if exists previsio_businesses_public_menu on public.businesses;
  create policy previsio_businesses_public_menu on public.businesses
    for select to anon, authenticated
    using (
      coalesce((enabled_modules->>'onlineOrders')::boolean, false) = true
    );
exception when undefined_table then
  raise notice 'skip public businesses policy';
when undefined_column then
  raise notice 'skip public businesses policy (schema mismatch)';
end $$;

comment on function public.previsio_my_business_ids() is 'Tenant membership for RLS — PreVisio';


